import base64
import subprocess
import sys
import os
import tempfile

# YOUR VIDEO DATA - Replace this with your actual base64-encoded video
# To generate: python3 -c "import base64; print(base64.b64encode(open('your_video.mp4', 'rb').read()).decode())"
ENCODED_VIDEO = """
"""

def play_video():
    """Decode and play the video without storing it permanently."""
    try:
        # Decode the base64 data
        print("Decoding video...")
        video_data = base64.b64decode(ENCODED_VIDEO.strip())
        
        # Create a temporary file
        with tempfile.NamedTemporaryFile(delete=False, suffix='.mp4') as tmp:
            tmp.write(video_data)
            tmp_path = tmp.name
        
        print(f"Playing video... (temp file: {tmp_path})")
        
        # Open with system default player
        if sys.platform == 'win32':
            os.startfile(tmp_path)
        elif sys.platform == 'darwin':  # macOS
            subprocess.run(['open', tmp_path])
        else:  # Linux
            subprocess.run(['xdg-open', tmp_path])
        
        # Wait for user to close the video
        input("\nPress Enter after the video finishes playing to clean up...\n")
        
    except Exception as e:
        print(f"Error: {e}")
    finally:
        # Clean up temp file
        if 'tmp_path' in locals() and os.path.exists(tmp_path):
            try:
                os.unlink(tmp_path)
                print("Temp file deleted.")
            except Exception as e:
                print(f"Could not delete temp file: {e}")

if __name__ == '__main__':
    play_video()

